window.PACK={"book":{"id":"diwan-mutanabbi","title":"ديوان المتنبي (مختارات)","type":"diwan","author":"المتنبي (مختارات) (ت ٣٥٤هـ)","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"abbasi","packVersion":"ab4525f752ba"},"items":[{"id":"diwan-mutanabbi:1","bookId":"diwan-mutanabbi","type":"poem","seq":1,"chapter":"البحر: وافر تام","title":"أتنكر يا ابن إسحق إخائي","page":"","text":"أتنكر يا ابن إسحق إخائي … وتحسب ماء غيري من إنائي ؟\nأأنطق فيك هجرا بعد علمي … بأنك خير من تحت السماء\nوما أربت على العشرين سني … فكيف مللت من طول البقاء\nوما استغرقت وصفك في مديحي … فأنقص منه شيئا بالهجاء\nوهبني قلت : هذا الصبح ليل … أيعمى العالمون عن الضياء ؟\nتطيع الحاسدين وأنت مرء … جعلت فداءه وهم فدائي\nوإن من العجائب أن تراني … فتعدل بي أقل من الهباء"},{"id":"diwan-mutanabbi:2","bookId":"diwan-mutanabbi","type":"poem","seq":2,"chapter":"قصائد","title":"أمن ازديارك في الدجى الرقباء","page":"","text":"أمن ازديارك في الدجى الرقباء … فلترك ما لم يأخذوا إعطاء\nقلق المليحة وهي مسك هتكها … ومسيرها في اليل وهي ذكاء\nأسفي على أسفي الذي دلهتني … عن علمه فيه علي خفاء\nوشكيتي فقد السقام لأنه … قد كان لما كان لي أعضاء\nمثلت عينك في حشاي جراحة … فتشابهها كلتاهما نجلاء\nنفذت علي السابري وربما … تندق فيه الصعدة السمراء\nأنا صخرة الوادي إذا ما زوحمت … وإذا نطقت فإنني الجوزاء\nوإذا خفيت على الغبي فعاذر … أن لا تراني مقلة عمياء\nشيم الليالي أن تشكك ناقتي … صدري بها أفضى أم البيداء\nبيني وبين أبي علي مثله … شم الجبال ومثلهن رجاء\nوعقاب لبنان وكيف بقطعها … وهو الشتاء وصيفهن شتاء\nلبس الثلوج بها علي مسالكي … فكأنها ببياضها سوداء\nوكذا الكريم إذا أقام ببلدة … سال النضار بها وقام الماء\nمن يهتدي في الفعل ما لا تهتدي … في القول حتى يفعل الشعراء\nفي كل يوم للقوافي جولة … في قلبه ولأذنه إصغاء\nفإذا سئلت فلا لأنك محوج … وإذا كتمت وشت بك الآلاء\nوأعدت حتى أنكر الإبداء … للشاكرين على الإله ثناء\nفبأيما قدم سعيت إلى العلى … إدم الهلال لأخمصيك حذاء\nولك الزمان من الزمان وقاية … ولك الحمام من الحمام فداء\nلو لم تكن من ذا الورى اللذ منك هو … حتى كأن مغيبه الأقذاء"},{"id":"diwan-mutanabbi:3","bookId":"diwan-mutanabbi","type":"poem","seq":3,"chapter":"قصائد","title":"لقد نسبوا الخيام إلى بلاء","page":"","text":"لقد نسبوا الخيام إلى بلاء … أبيت قبوله كل الإباء\nوما سلمت فوقك للثريا … ولا سلمت فوقك للسماء\nوقد أوحشت أرض الشام حتى … سلبت ربوعها ثوب البهاء\nتنفس والعواصم منك عشر … فتعرف طيب ذلك في الهواء"},{"id":"diwan-mutanabbi:4","bookId":"diwan-mutanabbi","type":"poem","seq":4,"chapter":"البحر: وافر تام","title":"أسامري ضحكة كل راء","page":"","text":"أسامري ضحكة كل راء … فطنت وكنت أغبى الأغبياء\nصغرت عن المديح فقلت أهجى … أنك ما صغرت عن الهجاء\nوما فكرت قبلك في محال … ولا جربت سيفي في هباء"},{"id":"diwan-mutanabbi:5","bookId":"diwan-mutanabbi","type":"poem","seq":5,"chapter":"البحر: كامل تام","title":"ألقلب أعلم يا عذول بدائه","page":"","text":"ألقلب أعلم يا عذول بدائه … وأحق منك بجفنه وبمائه\nفومن أحب لأعصينك في الهوى … قسما به وبحسنه وبهائه\nأأحبه وأحب فيه ملامة ؟ … إن الملامة فيه من أعدائه\nعجب الوشاة من اللحاة وقولهم … دع ما نراك ضعفت عن إخفائه\nما الخل إلا من أود بقلبه … وأرى بطرف لا يرى بسوائه\nإن المعين على الصبابة بالأسى … أولى برحمة ربها وإخائه\nمهلا فإن العذل من أسقامه … وترفقا فالسمع من أعضائه\nوهب الملامة في اللذاذة كالكرى … مطرودة بسهاده وبكائه\nإن القتيل مضرجا بدموعه … مثل القتيل مضرجا بدمائه\nوالعشق كالمعشوق يعذب قربه … للمبتلى وينال من حوبائه"},{"id":"diwan-mutanabbi:6","bookId":"diwan-mutanabbi","type":"poem","seq":6,"chapter":"البحر: كامل تام","title":"عذل العواذل حول قلبي التائه","page":"","text":"عذل العواذل حول قلبي التائه … وهوى الأحبة منه في سودائه\nيشكو الملام إلى اللوائم حره … ويصد حين يلمن عن برحائه\nوبمهجتي يا عاذلي الملك الذي … اسخطت كل الناس في ارضائه\nإن كان قد ملك القلوب فإنه … ملك الزمان بأرضه وسمائه\nالشمس من حساده والنصر من … قرنائه والسيف من أسمائه\nأين الثلاثة من ثلاث خلاله … من حسنه وإبائه ومضائه\nمضت الدهور وما أتين بمثله … ولقد أتى فعجزن عن نظرائه"},{"id":"diwan-mutanabbi:7","bookId":"diwan-mutanabbi","type":"poem","seq":7,"chapter":"البحر: خفيف تام","title":"إنما التهنئات للأكفاء","page":"","text":"إنما التهنئات للأكفاء … ولمن يدني من البعداء\nوأنا منك لا يهنئ عضو … بالمسرات سائر الأعضاء\nمستقل لك الديار ولو كا … ن نجوما آجر هذا البناء\nأنت أعلى محلة أن تهنا … بمكان في الأرض أو في السماء\nولك الناس والبلاد وما يس … رح بين الغبراء والخضراء\nإنما يفخر الكريم أبو المس … ك بما يبتني من العلياء\nوبأيامه التي انسلخت عن … ه وما دراه سوى الهيجاء\nوبما أثرت صوارمه البي … ض له في جماجم الأعداء\nلا بما يبتني الحواضر في الري … ف وما يطبي قلوب النساء\nتفضح الشمس كلما ذرت الشم … س بشمس منيرة سوداء\nإن في ثوبك الذي المجد فيه … لضياء يزري بكل ضياء\nإنما الجلد ملبس وابيضاض ال … نفس خير من ابيضاض القباء\nكرم في شجاعة وذكاء … في بهاء وقدرة في وفاء\nيارجاء العيون في كل أرض … لم يكن غير أن أراك رجائي\nفارم بي ما أردت مني فإني … أسد القلب آدمي الرواء\nوفؤادي من الملوك وإن كا … ن لساني يرى من الشعراء"},{"id":"diwan-mutanabbi:8","bookId":"diwan-mutanabbi","type":"poem","seq":8,"chapter":"البحر: متقارب تام","title":"ألا كل ماشية الخيزلى","page":"","text":"ألا كل ماشية الخيزلى … فدى كل ماشية الهيذبى\nوكل نجاة بجاوية … خنوف وما بي حسن المشى\nولكنهن حبال الحياة … وكيد العداة وميط الأذى\nضربت بها التيه ضرب القما … ر إما لهذا وإما لذا\nإذا فزعت قدمتها الجياد … وبيض السيوف وسمر القنا\nفمرت بنخل وفي ركبها … عن العالمين وعنه غنى\nوأمست تخيرنا بالنقا … ب وادي المياه ووادي القرى\nوردنا الرهيمة في جوزه … وباقيه أكثر مما مضى\nفلما أنخنا ركزنا الرما … ح فوق مكارمنا والعلى\nوبتنا نقبل أسيافنا … ونمسحها من دماء العدى\nلتعلم مصر ومن بالعراق … ومن بالعواصم أني الفتى\nوأني وفيت وأني أبيت … وأني عتوت على من عتا\nوماذا بمصر من المضحكات … ولكنه ضحك كالبكا\nبها نبطي من أهل السواد … يدرس أنساب أهل الفلا\nوأسود مشفره نصفه … يقال له أنت بدر الدجى\nوشعر مدحت به الكركدن … بين القريض وبين الرقى\nفما كان ذلك مدحا له … ولكنه كان هجو الورى\nوقد ضل قوم بأصنافهم … وأما بزق رياح فلا"},{"id":"diwan-mutanabbi:9","bookId":"diwan-mutanabbi","type":"poem","seq":9,"chapter":"البحر: طويل","title":"ولا عيب فيهم غير أن سيوفهم","page":"","text":"ولا عيب فيهم غير أن سيوفهم … بهن فلول من قراع الكتائب\nتخيرن من أزمان يوم حليمة … إلى اليوم قد جربن كل التجارب"},{"id":"diwan-mutanabbi:10","bookId":"diwan-mutanabbi","type":"poem","seq":10,"chapter":"البحر: وافر تام","title":"رأيتك توسع الشعراء نيلا","page":"","text":"رأيتك توسع الشعراء نيلا … حديثهم المولد والقديما\nفتعطي من بقى مالا جسيما … وتعطي من مضى شرفا عظيما\nسمعتك منشدا بيتي زياد … نشيدا مثل منشده كريما\nفما أنكرت موضعه ولكن … غبطت بذاك أعظمه الرميما"},{"id":"diwan-mutanabbi:11","bookId":"diwan-mutanabbi","type":"poem","seq":11,"chapter":"البحر: طويل","title":"أغالب فيك الشوق والشوق أغلب","page":"","text":"أغالب فيك الشوق والشوق أغلب … وأعجب من ذا الهجر والوصل أعجب\nأما تغلط الأيام في بأن أرى … بغيضا تنائي أو حبيبا تقرب\nوكم لظلام الليل عندك من يد … تخبر أن المانوية تكذب\nوقاك ردى الأعداء تسري إليهم … وزارك فيه ذو الدلال المحجب\nويوم كليل العاشقين كمنته … أراقب فيه الشمس أيان تغرب\nألا ليت شعري هل أقول قصيدة … فلا أشتكي فيها ولا أتعتب\nوبي ما يذود الشعر عني أقله … ولكن قلبي يا ابنة القوم قلب\nوأخلاق كافور إذا شئت مدحه … وإن لم أشأ تملي علي وأكتب\nإذا ترك الانسان أهلا وراءه … ويمم كافورا فما يتغرب\nفتى يملأ الأفعال رأيا وحكمة … ونادرة أحيان يرضى ويغضب\nتزيد عطاياه على اللبث كثرة … وتلبث أمواه السحاب فتنضب\nأبا المسك هل في الكأس فضل أناله … فإني أغني منذ حين وتشرب\nإذا لم تنط بي ضيعة أو ولا ية … فجودك يكسوني وشغلك يسلب\nيضاحك في ذا العيد كل حبيبه … حذائي وأبكي من أحب وأندب\nأحن إلى أهلي وأهوى لقاءهم … وأين من المشتاق عنقاء مغرب\nفإن لم يكن إلا ابو المسك أو هم … فإنك أحلى في فؤادي وأعذب"},{"id":"diwan-mutanabbi:12","bookId":"diwan-mutanabbi","type":"poem","seq":12,"chapter":"البحر: منسرح","title":"أحسن ما يخضب الحديد به أحسن ما يخضب الحديد به","page":"","text":"أحسن ما يخضب الحديد به أحسن ما يخضب الحديد به … وخاضبيه النجيع والغضب\nفلا تشيننه بالنضار فما … يجتمع الماء فيه والذهب"},{"id":"diwan-mutanabbi:13","bookId":"diwan-mutanabbi","type":"poem","seq":13,"chapter":"البحر: وافر تام","title":"أيدري ما أرابك من يريب","page":"","text":"أيدري ما أرابك من يريب … وهل ترقي إلى الفلك الخطوب\nوجسمك فوق همة كل داء … فقرب اقلها منه عجيب\nوكيف تعلك الدنيا بشيء … وأنت لعلة الدنيا طبيب\nوكيف تنوبك الشكوى بداء … وأنت المستغاث لما ينوب\nإذا داء هفا بقراط عنه … فلم يعرف لصاحبه ضريب\nبسيف الدولة الوضاء تمسي … جفوني تحت شمس ما تغيب\nفأغزو من غزا وبه اقتداري … وأرمي من رمى وبه أصيب"},{"id":"diwan-mutanabbi:14","bookId":"diwan-mutanabbi","type":"poem","seq":14,"chapter":"البحر: طويل","title":"وأسود أما القلب منه فضيق","page":"","text":"وأسود أما القلب منه فضيق … نخيب وأما بطنه فرحيب\nيموت به غيظا على الدهر أهله … كما مات غيظا فاتك وشبيب\nإذا عدمت الأصل والعقل والندى … فما لحياة في جنابك طيب"},{"id":"diwan-mutanabbi:15","bookId":"diwan-mutanabbi","type":"poem","seq":15,"chapter":"البحر: مجزوء الكامل","title":"لأحبتي أن يملأوا","page":"","text":"لأحبتي أن يملأوا … بالصافيات الأكوبا\nوعليهم أن يبذلوا … وعلي أن لا أشرب\nحتى تكون الباترا … ت المسمعات فأطربا"},{"id":"diwan-mutanabbi:16","bookId":"diwan-mutanabbi","type":"poem","seq":16,"chapter":"البحر: بسيط تام","title":"ألمجلسان على التمييز بينهما","page":"","text":"ألمجلسان على التمييز بينهما … مقابلان ولكن أحسنا الأدبا\nإذا صعدت الى ذا مال ذا رهبا … وإن صعدت إلى ذا مال ذا رهبا\nفلم ؟ يهابك مالا حس يردعه … إني لأبصر من فعليهما عجبا"},{"id":"diwan-mutanabbi:17","bookId":"diwan-mutanabbi","type":"poem","seq":17,"chapter":"البحر: وافر تام","title":"تعرض لي السحاب وقد قفلنا","page":"","text":"تعرض لي السحاب وقد قفلنا … فقلت إليك إن معي السحابا\nفشم في القبة الملك المرجى … فأمسك بعدما عزم انسكابا"},{"id":"diwan-mutanabbi:18","bookId":"diwan-mutanabbi","type":"poem","seq":18,"chapter":"البحر: مخلع البسيط","title":"الطيب مما غنيت عنه","page":"","text":"الطيب مما غنيت عنه … كفى بقرب الأمير طيبا\nيبني به ربنا المعالي … كما بكم يغفر الذنوبا"},{"id":"diwan-mutanabbi:19","bookId":"diwan-mutanabbi","type":"poem","seq":19,"chapter":"البحر: طويل","title":"ألا ما لسيف الدولة اليوم عاتبا","page":"","text":"ألا ما لسيف الدولة اليوم عاتبا … فداه الورى أمضى السيوف مضاربا\nومالي إذا ما اشتقت أبصرت دونه … تنائف لا اشتاقها وسباسبا\nوقد كان يدني مجلسي من سمائه … أحادث فيها بدرها والكواكبا\nحنانيك مسؤولا ولبيك داعيا … وحسبي موهوبا وحسبك واهبا\nأهذا جزاء الصدق إن كنت صادقا … أهذا جزاء الكذب إن كنت كاذبا\nوإن كان ذنبي كل ذنب فإنه … محا الذنب كل المحو من جاء تائبا"},{"id":"diwan-mutanabbi:20","bookId":"diwan-mutanabbi","type":"poem","seq":20,"chapter":"البحر: بسيط تام","title":"لما نسبت فكنت ابنا لغير أب","page":"","text":"لما نسبت فكنت ابنا لغير أب … ثم اختبرت فلم ترجع إلى أدب\nسميت بالذهبي اليوم تسمية … مشتقة من ذهاب العقل لا الذهب\nملقب بك ما لقبت ويك يه … يا أيها اللقب الملقى على اللقب"},{"id":"diwan-mutanabbi:21","bookId":"diwan-mutanabbi","type":"poem","seq":21,"chapter":"البحر: بسيط تام","title":"يا أخت خير أخ يا بنت خير أب","page":"","text":"يا أخت خير أخ يا بنت خير أب … كناية بهما عن أشرف النسب\nغدرت يا موت كم أفنيت من عدد … بمن أصبت وكم أسكت من لجب\nوكم صحبت أخاها في منازلة … وكم سألت فلم يبخل ولم تخب\nطوى الجزيرة حتى جاءني خبر … فزعت فيه بآمالي إلى الكذب\nحتى إذا لم يدع لي صدقه أملا … شرقت بالدمع حتى كاد يشرق بي\nتعثرت به في الأفواه ألسنها … والبرد في الطرق والأقلام في الكتب\nأرى العراق طويل الليل مذ نعيت … فكيف ليل فتى الفتيان في حلب\nيظن أن فؤادي غير ملتهب … وأن دمع جفوني غير منسكب\nبلى وحرمة من كانت مراعية … لحرمة المجد والقصاد والأدب\nومن مضت غير موروت خلائقها … وإن مضت يدها موروثة النشب\nوهمها في العلى والمجد ناشئة … وهم أترابها في اللهو واللعب\nوإن تكن خلقت أنثى لقد خلقت … كريمة غير انثى العقل والحسب\nوإن تكن تغلب الغلباء عنصرها … فإن في الخمر معنى ليس في العنب\nفليت طالعة الشمسين غائبة … وليت غائبة الشمسين لم تغب\nوليت عين التي آب النهار بها … فداء عين التي زالت ولم تؤب\nفما تقلد بالياقوت مشبهها … ولا تقلد بالهندية القضب\nولا ذكرت جميلا من صنائعها … إلا بكيت ولا ود بلا سبب\nومن تفكر في الدنيا ومهجته … أقامه الفكر بين العجز والتعب"},{"id":"diwan-mutanabbi:22","bookId":"diwan-mutanabbi","type":"poem","seq":22,"chapter":"البحر: متقارب تام","title":"لقد أصبح الجرذ المستغير لقد أصبح الجرذ المستغير","page":"","text":"لقد أصبح الجرذ المستغير لقد أصبح الجرذ المستغير … أسير المنايا صريع العطب\nرماه الكناني والعامري … وتلاه للوجه فعل العرب\nكلا الرجلين اتلى قتله … فأيكما غل حر السلب\nوأيكما كان من خلفه … فان به عضة في الذنب"},{"id":"diwan-mutanabbi:23","bookId":"diwan-mutanabbi","type":"poem","seq":23,"chapter":"البحر: مجزوء الكامل","title":"أنا عاتب لتعتبك","page":"","text":"أنا عاتب لتعتبك … متعجب لتعجبك\nاذ كنت حين لقيتني … متوجعا لتغيبك\nفشغلت عن رد السلا … م كان شغلي عنك بك"},{"id":"diwan-mutanabbi:24","bookId":"diwan-mutanabbi","type":"poem","seq":24,"chapter":"البحر: مجتث","title":"ما أنصف القوم ضبه","page":"","text":"ما أنصف القوم ضبه … وأمه الطرطبه\nوإنما قلت ما قل … ت رحمة لا محبه\nوحيلة لك حتى … عذرت لو كنت تأبه\nوما عليك من القت … ل إنما هي ضربه\nيا قاتلا كل ضيف … غناه ضيح وعلبه\nوخوف كل رفيق … ب أين خلف عجبه\nكذا خلقت ومن ذا ال … وكيف ترغب فيه\nما كنت إلا ذبابا … نفتك عنا مذبه\nوإن يخنك فعمري … ر إنما هي سبه\nأو آنستك المخازي … فإنها لك نسبه\nوإن عرفت مرادي … تكشفت عنك كربه\nوإن جهلت مرادي … فإنه بك أشبه"},{"id":"diwan-mutanabbi:25","bookId":"diwan-mutanabbi","type":"poem","seq":25,"chapter":"البحر: وافر تام","title":"فدتك الخيل وهي مسومات","page":"","text":"فدتك الخيل وهي مسومات … وبيض الهند وهي مجردات\nوصفتك في قواف سائرات … وقد بقيت وإن كثرت صفات\nأفاعيل الورى من قبل دهم … وفعلك في فعالهم شيات"},{"id":"diwan-mutanabbi:26","bookId":"diwan-mutanabbi","type":"poem","seq":26,"chapter":"البحر: متقارب تام","title":"أرى مرهفا مدهش الصيقلين","page":"","text":"أرى مرهفا مدهش الصيقلين … وبابه كل غلام عتا\nأتأذن لي ولك السابقات … أجربه لك في ذا الفتى"},{"id":"diwan-mutanabbi:27","bookId":"diwan-mutanabbi","type":"poem","seq":27,"chapter":"البحر: بسيط تام","title":"أنصر بجودك ألفاظا تركت بها","page":"","text":"أنصر بجودك ألفاظا تركت بها … في الشرق والغرب من عاداك مكبوتا\nفقد نظرتك حتى حان مرتحلي … وذا الوداع فكن أهلا لما شيتا"},{"id":"diwan-mutanabbi:28","bookId":"diwan-mutanabbi","type":"poem","seq":28,"chapter":"البحر: كامل تام","title":"سرب محاسنه حرمت ذواتها","page":"","text":"سرب محاسنه حرمت ذواتها … داني الصفات بعيد موصوفاتها\nأوفى فكنت إذا رميت بمقلتي … بشرا رأيت أرق من عبراتها\nيستاق عيسهم أنيني خلفها … تتوهم الزفرات زجر حداتها\nوكأنها شجر بدت لكنها … شجر حنيت الموت من ثمراتها\nلا سرت من إبل لو اني فوقها … لمحت حرارة مدمعي سماتها\nوحملت ما حملت من هذي المها … وحملت ما حملت من حسراتها\nإني على شغفي بما في خمرها … لأعف عما في سرابيلاتها\nوترى المروة والفتوة والأبو … ة في كل مليحة ضراتها\nتكبو وراءك يا ابن أحمد قرح … ليست قوائمهن من آلاتها\nلا خلق أسمح منك إلا عارف … بك راء نفسك لم يقل لك هاتها\nكرم تبين في كلامك ماثلا … ويبين عتق الخيل في أصواتها\nأقبلتها غرر الجياد كأنما … وتعودك الآساد من غاباتها\nوالجن من ستراتها والوحش من … فلواتها والطير من وكناتها\nذكر الأنام لنا فكان قصيدة … كنت البديع الفرد من أبياتها\nألثابتين فروسة كجلودها … كمماتها ومماتها كحياتها\nفاليوم صرت إلى الذي لو أنه … مثل القلوب بلا سويداواتها\nمسترخص نظر اليه بما به … نظرت وعثرة رجله بدياتها"},{"id":"diwan-mutanabbi:29","bookId":"diwan-mutanabbi","type":"poem","seq":29,"chapter":"البحر: وافر تام","title":"لهذا اليوم بعد غد أريج","page":"","text":"لهذا اليوم بعد غد أريج … ونار في العدو لها أجيج\nتبيت بها الحواضن آمنات … وتسلم في مسالكها الحجيج\nفلا زالت عداتك حيث كانت … فرائس أيها الأسد المهيج\nعرفتك والصفوف معبآت … وأنت بغير سيفك لا تعيج\nووجه … اذا يسجو فكيف إذا يموج\nبأرض تهلك الأشواط فيها … إذا ملئت من الركض الفروج\nتحاول نفس ملك الروم فيها … فتفديه رعيته العلوج\nأبالغمرات توعدنا النصارى … ونحن نجومها وهي البروج\nوفينا السيف حملته صدوق … اذا لاقى وغارته لجوج\nفإن يقدم فقد زرنا سمندو … وإن يحجم فموعدنا الخليج"},{"id":"diwan-mutanabbi:30","bookId":"diwan-mutanabbi","type":"poem","seq":30,"chapter":"البحر: منسرح","title":"جارية ما لجسمها روح","page":"","text":"جارية ما لجسمها روح … بالقلب من حبها تباريح\nفي كفها طاقة تشير بها … لكل طيب من طيبها ريح\nسأشرب الكأس عن إشارتها … ودمع عيني في الخد مسفوح"},{"id":"diwan-mutanabbi:31","bookId":"diwan-mutanabbi","type":"poem","seq":31,"chapter":"البحر: طويل","title":"بأدنى ابتسام منك تحيا القرائح","page":"","text":"بأدنى ابتسام منك تحيا القرائح … وتقوى من الجسم الضعيف الجوارح\nومن ذا الذي يقضي حقوقك كلها … ومن ذا الذي يرضي سوى من تسامح\nوقد تقبل العذر الخفي تكرما … فما بال عذري واقفا وهو واضح\nوان محالا اذ بك العيش أن أرى … وجسمك معتل وجسمي صالح\nوما كان ترك الشعر إلا لأنه … تقصر عن وصف الأمير المدائح"},{"id":"diwan-mutanabbi:32","bookId":"diwan-mutanabbi","type":"poem","seq":32,"chapter":"البحر: وافر تام","title":"يقاتلني عليك الليل جدا","page":"","text":"يقاتلني عليك الليل جدا … ومنصرفي له أمضى السلاح\nلأني كلما فارقت طرفي … بعيد بين جفني والصباح"},{"id":"diwan-mutanabbi:33","bookId":"diwan-mutanabbi","type":"poem","seq":33,"chapter":"البحر: وافر تام","title":"أباعث كل مكرمة طموح","page":"","text":"أباعث كل مكرمة طموح … وفارس كل سلهبة سبوح\nوطاعن كل نجلاء غموس … وعاصي كل عذال نصيح\nسقاني الله قبل الموت يوما … دم الأعداء من جوف الجروح"},{"id":"diwan-mutanabbi:34","bookId":"diwan-mutanabbi","type":"poem","seq":34,"chapter":"البحر: كامل تام","title":"إن القوافي لم تنمك وإنما","page":"","text":"إن القوافي لم تنمك وإنما … محقتك حتى صرت مالا يوجد\nفكأن أذنك فوك حين سمعتها … وكأنها مما سكرت المرقد"},{"id":"diwan-mutanabbi:35","bookId":"diwan-mutanabbi","type":"poem","seq":35,"chapter":"البحر: كامل تام","title":"أليوم عهدكم فأين الموعد ؟","page":"","text":"أليوم عهدكم فأين الموعد ؟ … هيهات ليس ليوم عهدكم غد\nالموت أقرب مخلبا من بينكم … والعيش أبعد منكم لا تبعدوا\nإن التي سفكت دمي بجفونها … لم تدر أن دمي الذي تتقلد\nقالت وقد رأت اصفراري من به … وتنهدت فأجبتها المتنهد\nفمضت وقد صبغ الحياء بياضها … لوني كما صبغ اللجين العسجد\nفرأيت قرن الشمس في قمر الدجى … متأودا غصن به يتأود\nوهواجل وصواهل ومناصل … وذوابل وتوعد وتهدد\nأبلت مودتها الليالي بعدنا … ومشى عليها الدهر وهو مقيد\nبرحت يا مرض الجفون بممرض … مرض الطبيب له وعيد العود\nفله بنو عبد العزيز بن الرضا … ولكل ركب عيسهم والفدفد\nمن في الأنام من الكرام ولا تقل … من فيك شأم سوى شجاع يقصد\nوتحيرت فيه الصفات لأنها … ألفت طرائقه عليها تبعد\nفي شأنه ولسانه وبنانه … وجنانه عجب لمن يتفقد\nأسد دم الأسد الهزبر خضابه … موت فريص الموت منه ترعد\nفالليل حين قدمت فيها أبيض … يبس النجيع عليه وهو مجرد\nأرض لها شرف سواها مثلها … لو كان مثلك في سواها يوجد\nأبدى العداة بك السرور كأنهم … فرحوا وعندهم المقيم المقعد\nقطعتهم حسدا أراهم ما بهم … فتقطعوا حسدا لمن لا يحسد\nبقيت جموعهم كأنك كلها … وبقيت بينهم كأنك مفرد\nكن حيث شئت تسر إليك ركابنا … فالأرض واحدة وأنت الأوحد\nوصن الحسام ولا تذله فإنه … يشكو يمينك والجماجم تشهد\nأنى يكون أبا البرية آدم … وأبوك والثقلان أنت محمد"},{"id":"diwan-mutanabbi:36","bookId":"diwan-mutanabbi","type":"poem","seq":36,"chapter":"البحر: بسيط تام","title":"فارقتكم فإذا ما كان عندكم","page":"","text":"فارقتكم فإذا ما كان عندكم … قبل الفراق أذى بعد الفراق يد\nإذا تذكرت ما بيني وبينكم … أعان قلبي على الشوق الذي أجد"},{"id":"diwan-mutanabbi:37","bookId":"diwan-mutanabbi","type":"poem","seq":37,"chapter":"البحر: بسيط تام","title":"عيد بأية حال عدت يا عيد","page":"","text":"عيد بأية حال عدت يا عيد … بما مضى أم لأمر فيك تجديد\nأما الاحبة فالبيداء دونهم … فليت دونك بيدا دونها بيد\nلم يترك الدهر من قلبي ولا كبدي … شيئا تتيمه عين ولا جيد\nيا ساقيي أخمر في كؤوسكما … أم في كؤوسكما هم وتسهيد ؟\nأصخرة أنا مالي لا تحكني … هذي المدام ولا هذي الاغاريد\nماذا لقيت من الدنيا وأعجبه … أني بما أنا باك منه محسود\nإني نزلت بكذابين ضيفهم … عن القرى وعن الترحال محدود\nجودث الرجال من الأيدي وجودهم … من اللسان ، فلا كانوا ولا الجود\nما يقبض الموت نفسا من نفوسهم … إلا وفي يده من نتنها عود\nصار الخصي إمام الآبقين بها … فالحر مستعبد والعبد معبود\nالعبد ليس لحر صالح بأخ … لو أنه في ثياب الحر مولود\nلا تشتري العبد إلا والعصا معه … إن العبيد لأنجاس مناكيد\nما كنت أحسبني أحيا إلى زمن … يسيء بي فيه عبد وهو محمود\nولا توهمت أن الناس قد فقدوا … وأن مثل أبي البيضاء موجود\nوأن ذا الأسود المثقوب مشفره … تطيعه ذي العضاريط الرعاديد\nجوعان يأكل من زادي ويمسكني … لكي يقال عظيم القدر مقصود\nمن علم الأسود المخصي مكرمة … أقومه البيض أم آباؤه الصيد\nأم أذنه في يد النخاس دامية … أم قدره وهو بالفلسين مردود\nأولى اللئام كويفير بمعذرة … في كل لؤم وبعض العذر تفنيد\nوذاك أن الفحول البيض عاجزة … عن الجميل فكيف الخصية السود ؟"},{"id":"diwan-mutanabbi:38","bookId":"diwan-mutanabbi","type":"poem","seq":38,"chapter":"البحر: مخلع البسيط","title":"يا من رأيت الحليم وغدا","page":"","text":"يا من رأيت الحليم وغدا … به وحر الملوك عبدا\nمال علي الشراب جدا … وأنت للمكرمات أهدى\nفإن تفضلت بانصرافي … عددته من لدنك رفدا"},{"id":"diwan-mutanabbi:39","bookId":"diwan-mutanabbi","type":"poem","seq":39,"chapter":"البحر: بسيط تام","title":"ما الشوق مقتنعا مني بذا الكمد","page":"","text":"ما الشوق مقتنعا مني بذا الكمد … حتى أكون بلا قلب ولا كبد\nولا الديار التي كان الحبيب بها … تشكو إلي ولا أشكو الى أحد\nما زال كل هزيم الودق ينحلها … والسقم ينحلني حتى حكت جسدي\nوكلما فاض دمعي غاض مصطبري … كأن ما سال من جفني من جلدي\nما دار في خلد الأيام لي فرح … أبا عبادة حتى درت في خلدي\nملك إذا امتلأت مالا خزانته … أذاقها طعم ثكل الأم للولد\nأي الأكف تباري الغيث ما اتفقا … حتى إذا افترقا عادت ولم يعد\nلم أجر غاية فكري منك في صفة … إلا وجدت مداها غاية الأبد"},{"id":"diwan-mutanabbi:40","bookId":"diwan-mutanabbi","type":"poem","seq":40,"chapter":"البحر: بسيط تام","title":"ماذا الوداع وداع الوامق الكمد","page":"","text":"ماذا الوداع وداع الوامق الكمد … هذا الوداع وداع الروح للجسد\nإذا السحاب زفته الريح مرتفعا … فلا عدا الرملة البيضاء من بلد\nويا فراق الأمير الرحب منزله … إن أنت فارقتنا يوما فلا تعد"},{"id":"diwan-mutanabbi:41","bookId":"diwan-mutanabbi","type":"poem","seq":41,"chapter":"البحر: خفيف تام","title":"كم قتيل كما قتلت شهيد","page":"","text":"كم قتيل كما قتلت شهيد … لبياض الطلى وورد الخدود\nوعيون المها ولا كعيون … فتكت بالمتيم المعمود\nعمرك الله ! هل رأيت بدورا … طلعت في براقع وعقود\nراميات بأسهم ريشها الهد … ب تشق القلوب قبل الجلود\nيترشفن من فمي رشفات … هن فيه أحلى من التوحيد\nكل شيء من الدماء حرام … شربه ما خلا ابنه العنقود\nفاسقنيها فدى لعينيك نفسي … من غزال وطارفي وتليدي\nشيب رأسي وذلتي ونحولي … ودموعي على هواك شهودي\nأي يوم سررتني بوصال … لم ترعني ثلاثة بصدود\nما مقامي بأرض نخلة إلا … م وبين الجفون والتسهيد\nفانقصي من عذابها أو فزيدي … ر بعيش معجل التنكيد\nأبدا أقطع البلاد ونجمي … في نحوس وهمتي في سعود\nولعلي مؤمل بعض ما أب … لغ باللطف من عزيز حميد\nعش عزيزا أو مت وأنت كريم … بين طعن القنا وخفق البنود\nأنا في أمة تداركها الل … ه غريب كصالح في ثمود"},{"id":"diwan-mutanabbi:42","bookId":"diwan-mutanabbi","type":"poem","seq":42,"chapter":"البحر: بسيط تام","title":"وشادن روح من يهواه في يده","page":"","text":"وشادن روح من يهواه في يده … سيف الصدود على أعلى مقلده\nما اهتز منه على عضو ليبتره … إلا اتقاه بترس من تجلده\nذم الزمان اليه من أحبته … ما ذم من بدره في حمد أحمده\nشمس إذا الشمس لاقته على فرس … تردد النور فيها من تردده\nإن يقبح الحسن إلا عند طلعته … والعبد يقبح إلا عند سيده\nقالت عن الرفد طب نفسا فقلت لها … لا يصدر الحر إلا بعد مورده\nلم أعرف الخير إلا مذ عرفت فتى … لم يولد الجود إلا عند مولده\nنفس تصغر نفس الدهر من كبر … لها نهى كهله في سن أمرده"},{"id":"diwan-mutanabbi:43","bookId":"diwan-mutanabbi","type":"poem","seq":43,"chapter":"البحر: كامل تام","title":"أمساور أم قرن شمس هذا","page":"","text":"أمساور أم قرن شمس هذا … أم ليث غاب يقدم الأستاذا\nشم ما انتضيت فقد تركت ذبابه … قطعا وقد ترك العباد جذاذا\nهبك ابن يزداذ حطمت وصحبه … أترى الورى أضحوا بني يزداذا\nغادرت أوجههم بحيث لقيتهم … أقفاءهم وكبودهم أفلاذا\nفي موقف وقف الحمام عليهم … في ضنكة واستحوذ استحواذا\nجمدت نفوسهم فلما جئتها … أجريتها وسقيتها الفولاذا\nما بين كرخايا إلى كلواذا … في جوشن وأخا أبيك معاذا\nأعجلت ألسنهم بضرب رقابهم … حتى يوافق عزمه الإنفاذا\nلم يلق قبلك من اذ اختلفت القنا … جعل الطعان من الطعان ملاذا"},{"id":"diwan-mutanabbi:44","bookId":"diwan-mutanabbi","type":"poem","seq":44,"chapter":"البحر: كامل أحذ","title":"برجاء جودك يطرد الفقر","page":"","text":"برجاء جودك يطرد الفقر … وبأن تعادى ينفد العمر\nفخر الزجاج بأن شربت به … وزرت على من عافها الخمر\nوسلمت منها وهي تسكرنا … حتى كأنك هابك السكر\nما يرتجى أحد لمكرمة … إلا الإل ه وأنت يا بدر"},{"id":"diwan-mutanabbi:45","bookId":"diwan-mutanabbi","type":"poem","seq":45,"chapter":"البحر: متقارب تام","title":"رضاك رضاي الذي أوثر","page":"","text":"رضاك رضاي الذي أوثر … وسرك سري فما أظهر\nكفتك المروءة ما تتقي … وأمنك الود ما تحذر\nوسركم في الحشا ميت … اذا أنشر السر لا ينشر\nكأني عصت مقلتي فيكم … وكاتمت القلب ما تبصر\nوإفشاء ما أنا مستودع … من الغدر والحر لا يغدر\nإذا ما قدرت على تطقة … فإني على تركها أقدر\nأصرف نفسي كما أشتهي … وأملكها والقنا أحمر\nدواليك يا سيفها دولة … وأمرك يا خير من يأمر\nأتاني رسولك مستعجلا … فلباه شعري الذي أذخر\nولو كان يوم وغى قاتما … للباه سيفي والأشقر\nفلا غفل الدهر عن أهله … فإنك عين بها ينظر"},{"id":"diwan-mutanabbi:46","bookId":"diwan-mutanabbi","type":"poem","seq":46,"chapter":"البحر: بسيط تام","title":"إن الأمير أدام الله دولته","page":"","text":"إن الأمير أدام الله دولته … لفاخر كسيت فخرا به مضر\nفي الشرب جارية من تحتها خشب … ما كان والدها جن ولا بشر\nقامت على فرد رجل من مهابته … وليس تعقل ما تأتي وما تذر"},{"id":"diwan-mutanabbi:47","bookId":"diwan-mutanabbi","type":"poem","seq":47,"chapter":"البحر: بسيط تام","title":"ألصوم والفطر والأعياد والعصر","page":"","text":"ألصوم والفطر والأعياد والعصر … منيرة بك حتى الشمس والقمر\nتري الأهلة وجها عم نائله … فما يخص به من دونها البشر\nما الدهر عندك إلا روضة أنف … يا من شمائله في دهره زهر\nما ينتهي لك في أيامه كرم … فلا انتهى لك أعوامه عمر\nفان حظك من تكرارها شرف … وحظ غيرك منها الشيب والكبر"},{"id":"diwan-mutanabbi:48","bookId":"diwan-mutanabbi","type":"poem","seq":48,"chapter":"البحر: بسيط تام","title":"ظلم لذا اليوم وصف قبل رؤيته","page":"","text":"ظلم لذا اليوم وصف قبل رؤيته … لا يصدق الوصف حتى يصدق النظر\nتزاحم الجيش حتى لم يجد سببا … إلى بساطك لي سمع ولا بصر\nفكنت أشهد مختصا وأغيبه … معاينا وعياني كله خبر\nأليوم يرفع ملك الروم ناظره … لأن عفوك منه عنده ظفر\nوإن أجبت بشيء عن رسائله … فما يزال على الأملاك يفتخر\nقد استراحت إلى وقت رقابهم … من السيوف وباقي القوم ينتظر\nوقد تبدلها بالقوم غيرهم … لكي تجم رؤوس القوم والقصر\nتشبيه جودك بالأمطار غادية … جود لكفك ثان ناله المطر\nتكسب الشمس منك النور طالعة … كما تكسب منها نوره القمر"},{"id":"diwan-mutanabbi:49","bookId":"diwan-mutanabbi","type":"poem","seq":49,"chapter":"البحر: كامل تام","title":"إني لأعلم واللبيب خبير","page":"","text":"إني لأعلم واللبيب خبير … أن الحياة وإن حرصت غرور\nورأيت كلا ما يعلل نفسه … بتعلة والى الفناء يصير\nأمجاور الديماس رهن قرارة … فيها الضياء بوجهه والنور\nما كنت أحسب قبل دفنك في الثرى … أن الكواكب في التراب تغور\nما كنت آمل قبل نعشك أن أرى … رضوى على أيدي الرجال تسير\nخرجوا به ولكل باك خلفه … صعقات موسى يوم دك الطور\nوالشمس في كبد السماء مريضة … والأرض واجفة تكاد تمور\nوحفيف أجنحة الملائك حوله … وعيون أهل اللاذقية صور\nحتى أتوا جدثا كأن ضريحه … في قلب كل موحد محفور\nبمزود كفن البلى من ملكه … مغف وإثمد عينه الكافور\nفيه السماحة والفصاحة والتقى … والبأس أجمع والحجى والخير\nوكأنما عيسى بن مريم ذكره … وكأن عازر شخصه المقبور"},{"id":"diwan-mutanabbi:50","bookId":"diwan-mutanabbi","type":"poem","seq":50,"chapter":"البحر: مخلع البسيط","title":"نال الذي نلت منه مني","page":"","text":"نال الذي نلت منه مني … لله ما تصنع الخمور\nوفي انصرافي إلى محلي … أآذن أيها الأمير ؟"},{"id":"diwan-mutanabbi:51","bookId":"diwan-mutanabbi","type":"poem","seq":51,"chapter":"البحر: خفيف تام","title":"ترك مدحيك كالهجاء لنفسي","page":"","text":"ترك مدحيك كالهجاء لنفسي … وقليل لك المديح الكثير\nغير أني تركت مقتضب الشع … ر لأمر مثلي به معذور\nوسجاياك ما دحاتك لالف … ظي وجود على كلامي يغير\nفسقى الله من أحب بكفي … ك وأسقاك أيهذا الأمير"},{"id":"diwan-mutanabbi:52","bookId":"diwan-mutanabbi","type":"poem","seq":52,"chapter":"البحر: بسيط تام","title":"زعمت أنك تنفي الظن عن أدبي","page":"","text":"زعمت أنك تنفي الظن عن أدبي … وأنت أعظم أهل الأرض مقدارا\nإني أنا الذهب المعروف مخبره … يزيد في السبك للدينار دينارا"},{"id":"diwan-mutanabbi:53","bookId":"diwan-mutanabbi","type":"poem","seq":53,"chapter":"البحر: كامل تام","title":"باد هواك صبرت أم لم تصبرا","page":"","text":"باد هواك صبرت أم لم تصبرا … وبكاك ان لم يجر دمعك أو جرى\nكم غر صبرك وابتسامك صاحبا … لما رآه وفي الحشا ما لا يرى\nأمر الفؤاد لسانه وجفونه … فكتمنه وكفى بجسمك مخبرا\nأعطى الزمان فما قبلت عطاءه … وأراد لي فأردت أن اتخيرا\nأرجان أيتها الجياد فإنه … عزمي الذي يذر الوشيج مكسرا\nلو كنت أفعل ما اشتهيت فعاله … ما شق كوكبك العجاج الأكدرا\nأمي أبا الفضل المبر أليتي … لأيممن أجل بحر جوهرا\nإن لم تغثني خيله وسلاحه … فمتى أقود إلى الأعادي عسكرا\nيا من إذا ورد البلاد كتابه … قبل الجيوش ثنى الجيوش تحيرا\nأنت الوحيد إذا ركبت طريقة … ومن الرديف وقد ركبت غضنفرا\nخلفت صفاتك في العيون كلامه … كالخط يملأ مسمعي من أبصرا\nبدرت إليك يد الزمان كأنها … وجدته مشغول اليدين مفكرا\nمن مبلغ الأعراب أني بعدها … جالست رسطاليس والاسكندرا\nأنا من جميع الناس أطيب منزلا … وأسر راحلة وأربحث متجرا\nزحل على أن الكواكب قومه … لو كان منك لكان أكرم معشرا"},{"id":"diwan-mutanabbi:54","bookId":"diwan-mutanabbi","type":"poem","seq":54,"chapter":"البحر: متقارب تام","title":"أرى ذلك القرب صار ازورارا","page":"","text":"أرى ذلك القرب صار ازورارا … وصار طويل السلام اختصارا\nتركتني اليوم في خجلة … أموت مرارا وأحيا مرارا\nأسارقك اللحظ مستحييا … وأزجر في الخيل مهري سرارا\nوأعلم أني إذا ما اعتذرت … إليك أراد اعتذاري اعتذارا\nكفرت مكارمك الباهرا … ت إن كان ذلك مني اختيارا\nولكن حمى الشعر إلا القلي … ل هم حمى النوم إلا غرارا\nوما أنا اسقمت جسمي به … ولا أنا أضرمت في القلب نارا\nفلا تلزمني ذنوب الزمان ، … إلي أساء وإياي ضارا\nوعندي لك الشرد السائرا … ت لا يختصصن من الأرض دارا\nقواف إذا سرن عن مقولي … وثبن الجبال وخضن البحارا\nولي فيك ما لم يقل قائل … وما لم يسر قمر حيث سارا\nفلو خلق الناس من دهرهم … لكانوا الظلام وكنت النهارا\nومن كنت بحرا له يا علي … لم يقبل الدر إلا كبارا"},{"id":"diwan-mutanabbi:55","bookId":"diwan-mutanabbi","type":"poem","seq":55,"chapter":"البحر: طويل","title":"مرتك ابن ابراهيم صافية الخمر","page":"","text":"مرتك ابن ابراهيم صافية الخمر … وهنئتها من شارب مسكر السكر\nرأيت الحميا في الزجاج بكفه … فشبهتها بالشمس في البدر في\nإذا ما ذكرنا جوده كان حاضرا … نأى أودنا يسعى على قدم الخضر"},{"id":"diwan-mutanabbi:56","bookId":"diwan-mutanabbi","type":"poem","seq":56,"chapter":"البحر: طويل","title":"بقية قوم آذنوا ببوار","page":"","text":"بقية قوم آذنوا ببوار … وأنضاء أسفار كشرب عقار\nنزلنا على حكم الرياح بمسجد … علينا لها ثوبا حصى وغبار\nخليلي ما هذا مناخا لمثلنا … فشدا عليها وارحلا بنهار\nولا تنكرا عصف الرياح فإنها … قرى كل ضيف بات عند سوار"},{"id":"diwan-mutanabbi:57","bookId":"diwan-mutanabbi","type":"poem","seq":57,"chapter":"البحر: بسيط تام","title":"لا تنكرن رحيلي عنك في عجل","page":"","text":"لا تنكرن رحيلي عنك في عجل … فإنني لرحيلي غير مختار\nوربما فارق الإنسان مهجته … يوم الوغى غير قال خشية العار\nوقد منيت بحساد أحاربهم … فاجعل نداك عليهم بعض أنصاري"},{"id":"diwan-mutanabbi:58","bookId":"diwan-mutanabbi","type":"poem","seq":58,"chapter":"البحر: وافر تام","title":"عذيري من عذارى من أمور","page":"","text":"عذيري من عذارى من أمور … سكن جوانحي بدل الخدور\nومبتسمات هيجاوات عصر … عن الأسياف ليس عن الثغور\nركبت مشمرا قدمي إليها … وكل عذافر قلق الضفور\nأوانا في بيوت البدو رحلي … وآونة على قتد البعير\nأعرض للرماح الصم نحري … وأنصب حر وجهي للهجير\nوأسري في ظلام الليل وحدي … كأني منه في قمر منير\nفقل في حاجة لم أقض منها … على شغفي بها شروى نقير\nفلو أني حسدت على نفيس … لجدت به لذي الجد العثور\nولكني حسدت على حياتي … وما خير الحياة بلا سرور\nفياابن كروس يا نصف أعمى … وإن تفخر فيا نصف البصير\nتعادينا لأنا غير لكن … وتبغضنا لأنا غير عور\nفلو كنت امرأ يهجى هجونا … ولكن ضاق فتر عن مسير"},{"id":"diwan-mutanabbi:59","bookId":"diwan-mutanabbi","type":"poem","seq":59,"chapter":"البحر: متقارب تام","title":"بسيطة مهلا سقيت القطارا","page":"","text":"بسيطة مهلا سقيت القطارا … تركت عيون عبيدي حيارى\nفظنوا النعام عليك النخيل … وظنوا الصوار عليك المنارا\nفأمسك صحبي بأكوارهم … وقد قصد الضحك فيهم وجارا"},{"id":"diwan-mutanabbi:60","bookId":"diwan-mutanabbi","type":"poem","seq":60,"chapter":"البحر: كامل تام","title":"أصبحت تأمر بالحجاب لخلوة","page":"","text":"أصبحت تأمر بالحجاب لخلوة … هيهات لست على الحجاب بقادر\nمن كان ضوء جبينه ونواله … لم يحجبا لم يحتجب عن ناظر\nفإذا احتجبت فأنت غير محجب … وإذا بطنت فأنت عين الظاهر"},{"id":"diwan-mutanabbi:61","bookId":"diwan-mutanabbi","type":"poem","seq":61,"chapter":"البحر: رمل تام","title":"لا تلومن اليهودي على","page":"","text":"لا تلومن اليهودي على … أن يرى الشمس فلا ينكرها\nإنما اللوم على حاسبها … ظلمة من بعد مايبصرها"},{"id":"diwan-mutanabbi:62","bookId":"diwan-mutanabbi","type":"poem","seq":62,"chapter":"البحر: خفيف تام","title":"كفرندي فرند سيفي الجراز","page":"","text":"كفرندي فرند سيفي الجراز … لذة العين عدة للبراز\nتحسب الماء خط في لهب النا … ر أدق الخطوط في الأحراز\nكلما رمت لونه منع النا … ظر موج كأنه منك هازي\nودقيق قذى الهباء أنيق … متوال في مستو هزهاز\nحملته حمائل الدهر حتى … هي محتاجة إلى خراز\nيا مزيل الظلام عني وروضي … يوم شربي ومعقلي في البراز\nواليماني الذي لو اسطعت كانت … مقلتي غمده من الإعزاز\nإن برقي إذا برقت فعالي … وصليلي اذا صللت ارتجازي\nلم أحملك معلما هكذا إلا … لضرب الرقاب والأجواز\nولقطعي بك الحديد عليها … فكلانا لجنسه اليوم غاز\nسله الركض بعد وهن بنجد … فتصدى للغيث أهل الحجاز\nوتمنيت مثله فكأني … طالب لابن صالح من يوازي\nليس كل السراة بالروذباري … ولا كل ما يطير بباز\nفارسي له من المجد تاج … كان من جوهر على أبرواز\nنفسه فوق كل أصل شريف … ولو أني له إلى الشمس عاز\nشغلت قلبه حسان المعالي … عن حسان الوجوه والأعجاز\nوكأن الفريد والدر واليا … قوت من لفظه وسام الركاز\nتقضم الجمر والحديد الأعادي … دونه قضم سكر الأهواز\nأيها الواسع الفناء وما في … ه مبيت لمالك المجتاز\nبك أضحى شبا الأسنة عندي … كشبا أسوق الجراد النوازي\nوحكى في اللحوم فعلك في الوف … ر فأودى بالعنتريس الكناز\nومن الناس من يجوز عليه … شعراء كأنها الخازباز\nوترى أنه البصير بهذا … وهو في العمي ضائع العكاز\nكل شعر نظير قائله في … ك وعقل المجيز عقل المجاز"},{"id":"diwan-mutanabbi:63","bookId":"diwan-mutanabbi","type":"poem","seq":63,"chapter":"البحر: وافر تام","title":"ألا أذن فما أذكرت ناسي","page":"","text":"ألا أذن فما أذكرت ناسي … ولا لينت قلبا وهو قاس\nولا شغل الأمير عن المعالي … ولا عن حق خالقه بكاس"},{"id":"diwan-mutanabbi:64","bookId":"diwan-mutanabbi","type":"poem","seq":64,"chapter":"البحر: وافر تام","title":"ألذ من المدام الخندريس","page":"","text":"ألذ من المدام الخندريس … وأحلى من معاطاة الكؤوس\nمعاطاة الصفائح والعوالي … وإقحامي خميسا في خميسي\nفموتي في الوغى عيشي لأني … رأيت العيش في أرب النفوس\nولو سقيتها بيدي نديم … أسر به لكان أبا ضبيس"},{"id":"diwan-mutanabbi:65","bookId":"diwan-mutanabbi","type":"poem","seq":65,"chapter":"البحر: وافر تام","title":"يقل له القيام على الرؤوس","page":"","text":"يقل له القيام على الرؤوس … وبذل المكرمات من النفوس\nإذا خانته في يوم ضحوك … فكيف تكون في يوم عبوس"},{"id":"diwan-mutanabbi:66","bookId":"diwan-mutanabbi","type":"poem","seq":66,"chapter":"البحر: سريع","title":"أنوك من عبد ومن عرسه","page":"","text":"أنوك من عبد ومن عرسه … من حكم العبد على نفسه\nوإنما يظهر تحكيمه … تحكم الإفساد في حسه\nما من يرى أنك في وعده … كمن يرى أنك في حبسه\nلا ينجز الميعاد في يومه … ولا يعي ما قال في أمسه\nفلا ترج الخير عند امرىء … مرت يد النخاس في رأسه\nوإن عراك الشك في نفسه … بحاله فانظر إلى جنسه\nفقلما يلؤم في ثوبه … إلا الذي يلؤم في غرسه\nمن وجد المذهب عن قدره … لم يجد المذهب عن قنسه"},{"id":"diwan-mutanabbi:67","bookId":"diwan-mutanabbi","type":"poem","seq":67,"chapter":"البحر: كامل تام","title":"هذي برزت لنا فهجت رسيسا","page":"","text":"هذي برزت لنا فهجت رسيسا … ثم انثنيت وما شفيت نسيسا\nوجعلت حظي منك حظي في الكرى … وتركتني للفرقدين جليسا\nقطعت ذياك الخمار بسكرة … وأدرت من خمر الفراق كؤوسا\nإن كنت ظاعنة فإن مدامعي … تكفي مزادكم وتروي العيسا\nحاشى لمثلك أن تكون بخيلة … ولمثل وجهك أن يكون عبوسا\nولمثل وصلك أن يكون ممنعا … ولمثل نيلك أن يكون خسيسا\nخود جنت بيني وبين عواذلي … حربا وغادرت الفؤاد وطيسا\nبيضاء يمنعها تكلم دلها … ورأيته فرأيت منه خميسا\nلما وجدت دواء دائي عندها … هانت علي صفات جالينوسا\nأبقى زريق للثغور محمدا … أبقى نفيس للنفيس نفيسا\nإن حل فارقت الخزائن ماله … أو سار فارقت الجسوم الروسا\nملك إذا عاديت نفسك عاده … ورضيت أوحش ما كرهت انيسا\nيا من نلوذ من الزمان بظله … أبدا ونطرد باسمه ابليسا\nصدق المخبر عنك دونك وصفه … من في العراق يراك في طرسوسا\nإني نثرت عليك درا فانتقد … كثر المدلس فاحذر التدليسا\nخير الطيور على القصور وشرها … يأؤى الخراب ويسكن الناؤوسا\nلو جادت الدنيا فدتك بأهلها … أو جاهدت كتبت عليك حبيسا"},{"id":"diwan-mutanabbi:68","bookId":"diwan-mutanabbi","type":"poem","seq":68,"chapter":"البحر: وافر تام","title":"مبيتي من دمشق على فراش","page":"","text":"مبيتي من دمشق على فراش … حشاه لي بحر حشاي حاش\nلقى ليل كعين الظبي لونا … وهم كالحميا في المشاش\nوشوق كالتوقد في فؤاد … كجمر في جوانح كالمحاش\nسقى الدم كل نصل غير ناب … وروى كل رمح غير راش\nفقد أضحى أبا الغمرات يكنى … كأن أبا العشائر غير فاش\nوقد نسي الحسين بما يسمى … ردى الأبطال أو غيث العطاش\nلقوه حاسرا في درع ضرب … دقيق النسج ملتهب الحواشي\nكأن على الجماجم منه نارا … وأيدي القوم أجنحة الفراش\nيدمي بعض أيدي الخيل بعضا … وما بعجاية أثر ارتهاش\nورائعها وحيد لم يرعه … تباعد جيشه والمستجاش\nكأن تلوي النشاب فيه … تلوي الخوص في سعف العشاش\nفيا بحر البحورولا أوري … ويا ملك الملوك ولا أحاشي\nكأنك ناظر في كل قلب … فما يخفى عليك محل غاش\nأأصبر عنك لم تبخل بشيء … ولم تقبل علي كلام واش\nتطاعن كل خيل كنت فيها … ولو كانوا النبيط على الجحاش\nأرى الناس الظلام وأنت نور … وإني منهم لإليك عاش\nبليت بهم بلاء الورد يلقى … أنوفا هن أولى بالخشاش\nعليك إذا هزلت مع الليالي … وحولك حين تسمن في هراش\nأتى خبر الأمير فقيل كروا … فقلت نعم ولو لحقوا بشاش\nوما وجد اشتياق كاشتياقي … ولا عرف انكماش كانكماشي\nفسرت اليك في طلب المعالي … وسار سواي في طلب المعاش"},{"id":"diwan-mutanabbi:69","bookId":"diwan-mutanabbi","type":"poem","seq":69,"chapter":"البحر: طويل","title":"إذا اعتل سيف الدولة اعتلت الأرض","page":"","text":"إذا اعتل سيف الدولة اعتلت الأرض … ومن فوقها والبأس والكرم المحض\nوكيف انتفاعي بالرقاد وإنما … بعلته يعتل في الأعين الغمض\nشفاك الذي يشفي بجودك خلقه … فإنك بحر كل بحر له بعض"},{"id":"diwan-mutanabbi:70","bookId":"diwan-mutanabbi","type":"poem","seq":70,"chapter":"البحر: طويل","title":"مضى الليل والفضل الذي لك لا يمضي","page":"","text":"مضى الليل والفضل الذي لك لا يمضي … ورؤياك أحلى في العيون من الغمض\nعلى أنني طوقت منك بنعمة … شهيد بها بعضي لغيري على بعضي\nسلام الذي فوق السماوات عرشه … تخص به يا خير ماش على الأرض"},{"id":"diwan-mutanabbi:71","bookId":"diwan-mutanabbi","type":"poem","seq":71,"chapter":"البحر: كامل تام","title":"فعلت بنا فعل السماء بأرضه","page":"","text":"فعلت بنا فعل السماء بأرضه … خلع الأمير وحقه لم نقضه\nفكأن صحة نسجها من لفظه … وكأن حسن نقائها من عرضه\nوإذا وكلت إلى كريم رأيه … في الجود بان مذيقه من محضه"},{"id":"diwan-mutanabbi:72","bookId":"diwan-mutanabbi","type":"poem","seq":72,"chapter":"البحر: طويل","title":"حشاشة نفس ودعت يوم ودعوا","page":"","text":"حشاشة نفس ودعت يوم ودعوا … فلم أدر أي الظاعنين أشيع\nحشاي على جمر ذكي من الهوى … وعيناي في روض من الحسن ترتع\nأتت زائرا ما خامر الطيب ثوبها … وكالمسك من أردانها يتضوع\nفما جلست حتى انثنت توسع الخطى … كفاطمة عن درها قبل ترضع\nفشرد إعظامي لها ما أتى بها … من النوم والتاع الفؤاد المفجع\nفيا ليلة ما كان أطول بتها … وسم الأفاعي عذب ما أتجرع\nتذلل لها واخضع على القرب والنوى … فما عاشق من لا يذل ويخضع\nولا ثوب مجد غير ثوب ابن أحمد … على أحد إلا بلؤم مرقع\nبذي كرم ما مر يوم وشمسه … على رأس أوفى ذمة منه تطلع\nفتى ألف جزء رأيه في زمانه … أقل جزيء بعضه الرأي أجمع\nفصيح متى ينطق تجد كل لفظة … أصول البراعات التي تتفرع\nبكف جواد لو حكتها سحابة … لما فاتها في الشرق والغرب موضع\nألا أيها القيل المقيم بمنبج … وهمته فوق السماكين توضع\nأليس عجيبا أن وصفك معجز … وأن ظنوني في فعاليك تظلع\nوأنك في ثوب وصدرك فيكما … على أنه من ساحة الأرض أوسع\nوقلبك في الدنيا ولو دخلت بنا … وبالجن فيه مادرت كيف ترجع\nألا كل سمح غيرك اليوم باطل … وكل مديح في سواك مضيع"},{"id":"diwan-mutanabbi:73","bookId":"diwan-mutanabbi","type":"poem","seq":73,"chapter":"البحر: كامل تام","title":"ألحزن يقلق والتجمل يردع","page":"","text":"ألحزن يقلق والتجمل يردع … والدمع بينهما عصي طيع\nيتنازعان دموع عين مسهد … هذا يجيء بها وهذا يرجع\nالنوم بعد أبي شجاع نافر … والليل معي والكواكب ظلع\nإني لأجبن عن فراق أحبتي … وتحس نفسي بالحمام فأشجع\nتصفو الحياة لجاهل أو غافل … عما مضى فيها وما يتوقع\nولمن يغالط في الحقائق نفسه … ويسومها طلب المحال فتطمع\nتتخلف الآثار عن أصحابها … حينا ويدركها الفناء فتتبع\nأين الذي الهرمان من بنيانه ، … ما قومه ، ما يومه ، ما المصرع ؟\nلم يرض قلب أبي شجاع مبلغ … قبل الممات ولم يسعه موضع\nكنا نظن دياره مملوءة … ذهبا فمات وكل دار بلقع\nبرد حشاي إن استطعت بلفظة … فلقد تضر إذا تشاء وتنفع\nما كان منك إلى خليل قبلها … ما يستراب به ولا ما يوجع\nولقد أراك وما تلم ملمة … إلا نفاها عنك قلب أصمع\nيا من يبدل كل يوم حلة … أنى رضيت بحلة لا تنزع ؟\nما زلت تخلعها على من شاءها … حتى لبست اليوم مالا تخلع\nما زلت تدفع كل أمر فادح … حتى أتى الأمر الذي لا يدفع\nقبحا لوجهك يا زمان فإنه … وجه له من كل قبح برقع\nأيموت مثل أبي شجاع فاتك … ويعيش حاسده الخصي الأوكع\nأبقيت أكذب كاذب أبقيته … وأخذت أصدق من يقول ويسمع\nوتركت أنتن ريحة مذمومة … وسلبت أطيب ريحة تتضوع\nولى وكل مخالم ومنادم … بعد اللزوم مشيع ومودع\nمن كان فيه لكل قوم ملجأ … ولسيفه في كل قوم مرتع\nإن حل في فرس ففيها ربها … كسرى تذل له الرقاب وتخضع\nأو حل في روم ففيها قيصر … أو حل في عرب ففيها تبع\nقد كان أسرع فارس في طعنة … فرسا ولكن المنية أسرع\nلا قلبت أيدي الفوارس بعده … رمحا ولا حملت جوادا أربع"},{"id":"diwan-mutanabbi:74","bookId":"diwan-mutanabbi","type":"poem","seq":74,"chapter":"البحر: خفيف تام","title":"بأبي من وددته فافترقنا","page":"","text":"بأبي من وددته فافترقنا … وقضى الله بعد ذاك اجتماعا\nفافترقنا حولا فلما التقينا … كان تسليمه علي وداعا"},{"id":"diwan-mutanabbi:75","bookId":"diwan-mutanabbi","type":"poem","seq":75,"chapter":"البحر: وافر تام","title":"به وبمثله شق الصفوف","page":"","text":"به وبمثله شق الصفوف … وزلت عن مباشرها الحتوف\nفدعه لقى فإنك من كرام … جواشنها الأسنة والسيوف"},{"id":"diwan-mutanabbi:76","bookId":"diwan-mutanabbi","type":"poem","seq":76,"chapter":"البحر: طويل","title":"ومنتسب عندي إلى من أحبه","page":"","text":"ومنتسب عندي إلى من أحبه … وللنبل حولي من يديه حفيف\nفهيج من شوقي وما من مذلة … حننت ولكن الكريم ألوف\nوكل وداد لا يدوم على الأذى … دوام ودادي للحسين ضعيف\nفإن يكن الفعل الذي ساء واحدا … فأفعاله اللائي سررن ألوف\nونفسي له نفسي الفداء لنفسه … ولكن بعض المالكين عنيف\nفإن كان يبغي قتلها يك قاتلا … بكفيه فالقتل الشريف شريف"},{"id":"diwan-mutanabbi:77","bookId":"diwan-mutanabbi","type":"poem","seq":77,"chapter":"البحر: وافر تام","title":"موقع الخيل من نداك طفيف موقع الخيل من نداك طفيف","page":"","text":"موقع الخيل من نداك طفيف موقع الخيل من نداك طفيف … ولو أن الجياد فيها ألوف\nومن اللفظ لفظة تجمع الوص … ف وذاك المطهم المعروف\nمالنا في الندى عليك اختيار … كل ما يمنح الشريف شريف"},{"id":"diwan-mutanabbi:78","bookId":"diwan-mutanabbi","type":"poem","seq":78,"chapter":"البحر: منسرح","title":"أعددت للغادرين أسيافا","page":"","text":"أعددت للغادرين أسيافا … أجدع منهم بهن آنافا\nلا يرحم الله أرؤسا لهم … أطرن عن هامهن أقحافا\nما ينقم السيف غير قلتهم … وأن تكون المئون آلافا\nيا شر لحم فجعته بدم … وزار للخامعات أجوافا\nوعدت ذا النصل من تعرضه … وخفت لما اعترضت إخلافا\nلا يذكر الخير إن ذكرت ولا … تتبعك المقلتان توكافا\nإذا امرؤ راعني بغدرته … أوردته الغاية التي خافا"},{"id":"diwan-mutanabbi:79","bookId":"diwan-mutanabbi","type":"poem","seq":79,"chapter":"البحر: منسرح","title":"أهون بطول الثواء والتلف","page":"","text":"أهون بطول الثواء والتلف … والسجن والقيد يا أبا دلف\nغير اختيار قبلت برك لي … والجوع يرضي الأسود بالجيف\nكن أيها السجن كيف شئت فقد … وطنت للموت نفس معترف\nلو كان سكناي فيك منقصة … لم يكن الدر ساكن الصدف"},{"id":"diwan-mutanabbi:80","bookId":"diwan-mutanabbi","type":"poem","seq":80,"chapter":"البحر: كامل تام","title":"أرق على أرق ومثلي يأرق","page":"","text":"أرق على أرق ومثلي يأرق … وجوى يزيد وعبرة تترقرق\nجهد الصبابة أن تكون كما أرى … عين مسهدة وقلب يخفق\nمالاح برق أو ترنم طائر … إلا انثنيت ولي فؤاد شيق\nجربت من نار الهوى ما تنطفي … نار الغضى وتكل عما تحرق\nوعذلت أهل العشق حتى ذقته … فعجبت كيف يموت من لا يعشق\nوعذرتهم وعرفت ذنبي أنني … عيرتهم فلقيت منهم ما لقوا\nأبني أبينا نحن أهل منازل … أبدا غراب البين فيها ينعق\nنبكي على الدنيا وما من معشر … جمعتهم الدنيا فلم يتفرقوا\nأين الأكاسرة الجبابرة الألى … كنزوا الكنوز فما بقين ولا بقوا\nفالموت آت والنفوس نفائس … والمستغر بما لديه الأحمق\nوالمرء يأمل والحياة شهية … والشيب أوقر والشبيبة أنزق\nولقد بكيت على الشباب ولمتي … مسودة ولماء وجهي رونق\nحذرا عليه قبل يوم فراقه … حتى لكدت بماء جفني أشرق\nأما بنو أوس بن معن الرضا … مسكية النفحات إلا أنها\nكبرت حول ديارهم لمابدت … منها الشموس وليس فيها المشرق\nوعجبت من أرض سحاب أكفهم … من فوقها وصخورها لا تورق\nلم يخلق الرحمن مثل محمد … أحدا وظني أنه لا يخلق\nأمطر علي سحاب جودك ثرة … وانظر إلي برحمة لا أغرق\nكذب ابن فاعلة يقول بجهله … مات الكرام وأنت حي يرزق"},{"id":"diwan-mutanabbi:81","bookId":"diwan-mutanabbi","type":"poem","seq":81,"chapter":"البحر: مجزوء الرجز","title":"أي محل أرتقي","page":"","text":"أي محل أرتقي … أي عظيم أتقي\nوكل ما قد خلق الل … هوما لم يخلق\nمحتقر في همتي … كشعرة في مفرقي"},{"id":"diwan-mutanabbi:82","bookId":"diwan-mutanabbi","type":"poem","seq":82,"chapter":"البحر: طويل","title":"لعينيك ما يلقى الفؤاد وما لقي","page":"","text":"لعينيك ما يلقى الفؤاد وما لقي … وللحب ما لم يبق مني وما بقي\nوما كنت ممن يدخل العشق قلبه … ولكن من يبصر جفونك يعشق\nوبين الرضى والسخط والقرب والنوى … مجال لدمع المقلة المترقرق\nوأحلى الهوى ما شك في الوصل ربه … وفي الهجر فهو الدهر يرجو ويتقي\nوغضبى من الإدلال سكرى من الصبى … شفعت إليها من شبابي بريق\nوأشنب معسول الثنيات واضح … سترت فمي عنه فقبل مفرقي\nوأجياد غزلان كجيدك زرنني … فلم أتبين عاطلا من مطوق\nوما كل من يهوى يعف إذا خلا … عفافي ويرضي الحب والخيل تلتقي\nسقى الله أيام الصبا ما يسرها … ويفعل فعل البابلي المعتق"},{"id":"diwan-mutanabbi:83","bookId":"diwan-mutanabbi","type":"poem","seq":83,"chapter":"البحر: وافر تام","title":"وذات غدائر لا عيب فيها","page":"","text":"وذات غدائر لا عيب فيها … سوى أن ليس تصلح للعناق\nإذا هجرت فعن غير اختيار … وإن زارت فعن غير اشتياق\nأمرت بأن تشال ففارقتنا … وما ألمت لحادثة الفراق"},{"id":"diwan-mutanabbi:84","bookId":"diwan-mutanabbi","type":"poem","seq":84,"chapter":"البحر: رجز تام","title":"ما للمروج الخضر والحدائق","page":"","text":"ما للمروج الخضر والحدائق … يشكو خلاها كثرة العوائق\nأقام فيها الثلج كالمرافق … يعقد فوق السن ريق الباصق\nثم مضى لا عاد من مفارق … بقائد من ذوبه وسائق\nكأنما الطخرور باغي آبق … يأكل من نبت قصير لاصق\nكقشرك الحبر عن المهارق … أروده منه بكالشوذانق\nبمطلق اليمنى طويل الفائق … عبل الشوى مقارب المرافق\nرحب اللبان نائه الطرائق … ذي منخر رحب وإطل لاحق\nمحجل نهد كميت زاهق … شادخة غرته كالشارق"},{"id":"diwan-mutanabbi:85","bookId":"diwan-mutanabbi","type":"poem","seq":85,"chapter":"البحر: متقارب تام","title":"لئن كان أحسن في وصفها","page":"","text":"لئن كان أحسن في وصفها … لقد فاته الحسن في الوصف لك\nلأنك بحر وإن البحار … لتأنف من حال هذي البرك\nكأنك سيفك لا ماملك … ت يبقى لديك ولا ما ملك\nفأكثر من جريها ما وهبت … وأكثر من مائها ما سفك\nأسأت وأحسنت عن قدرة … ودرت على الناس دور الفلك"},{"id":"diwan-mutanabbi:86","bookId":"diwan-mutanabbi","type":"poem","seq":86,"chapter":"البحر: سريع","title":"لم تر من نادمت إلاكا","page":"","text":"لم تر من نادمت إلاكا … لا لسوى ودك لي ذاكا\nولا لحبيها ولكنني … أمسيت أرجوك وأخشاكا"},{"id":"diwan-mutanabbi:87","bookId":"diwan-mutanabbi","type":"poem","seq":87,"chapter":"البحر: وافر تام","title":"فدى لك من يقصر عن مداكا","page":"","text":"فدى لك من يقصر عن مداكا … فلا ملك إذن إلا فداكا\nولو قلنا فدى لك من يساوي … دعونا بالبقاء لمن قلاكا\nأروح وقد ختمت على فؤادي … بحبك أن يحل به سواكا\nوقد حملتني شكرا طويلا … ثقيلا لا أطيق به حراكا\nأحاذر أن يشق على المطايا … فلا تمشي بنا إلا سواكا\nلعل الله يجعله رحيلا … يعين على الإقامة في ذراكا\nفلو أني استطعت خفضت طرفي … فلم أبصر به حتى أراكا\nوكيف الصبر عنك وقد كفاني … نداك المستفيض وما كفاكا\nأتتركني وعين الشمس نعلي … فتقطع مشيتي فيها الشراكا\nأرى أسفي وما سرنا شديدا … فكيف إذا غدا السير ابتراكا\nوهذا الشوق قبل البين سيف … وها أنا ما ضربت وقد أحاكا\nإذا التوديع أعرض قال قلبي : … عليك الصمت لا صاحبت فاكا\nوكم دون الثوية من حزين … يقول له قدومي ذا بذاكا\nكم طرب المسامع ليس يدري … أيعجب من ثنائي أم علاكا\nأغر له شمائل من أبيه … غدا يلقى بنوك بها أباكا\nوفي الأحباب مختص بوجد … وآخر يدعي معه اشتراكا\nاذا اشتبهت دموع في خدود … تبين من بكى ممن تباكى\nومن اعتاض عنك إذا افترقنا … وكل الناس زور ما خلاكا\nوما أنا غير سهم في هواء … يعود ولم يجد فيه امتساكا\nحيي من إل هي أن يراني … وقد فارقت دارك واصطفاكا"},{"id":"diwan-mutanabbi:88","bookId":"diwan-mutanabbi","type":"poem","seq":88,"chapter":"البحر: خفيف تام","title":"قد بلغت الذي أردت من البر","page":"","text":"قد بلغت الذي أردت من البر … ومن حق ذا الشريف عليكا\nوإذا لم تسر إلى الدار في وق … تك ذا خفت أن تسير إليكا"},{"id":"diwan-mutanabbi:89","bookId":"diwan-mutanabbi","type":"poem","seq":89,"chapter":"البحر: طويل","title":"أماتكم من قبل موتكم الجهل","page":"","text":"أماتكم من قبل موتكم الجهل … وجركم من خفة بكم النمل\nوليد أبي الطيب الكلب مالكم … فطنتم إلى الدعوى ومالكم عقل\nولو ضربتكم منجنيقي وأصلكم … قوي لهدتم فكيف ولا أصل\nولو كنتم ممن يدبر أمره … لما صرتم نسل الذي ماله نسل"},{"id":"diwan-mutanabbi:90","bookId":"diwan-mutanabbi","type":"poem","seq":90,"chapter":"البحر: بسيط تام","title":"لا خيل عندك تهديها ولا مال","page":"","text":"لا خيل عندك تهديها ولا مال … فليسعد النطق إن لم تسعد الحال\nواجز الأمير الذي نعماه فاجئة … بغير قول ونعمى الناس أقوال\nفربما جزت الإحسان موليه … خريدة من عذارى الحي مكسال\nوإن تكن محكمات الشكل تمنعني … ظهور جري فلي فيهن تصهال\nوما شكرت لأن المال فرحني … سيان عندي إكثار وإقلال\nلا يدرك المجد إلا سيد فطن … لما يشق على السادات فعال\nتدري القناة إذا اهتزت براحته … أن الشقي بها خيل وأبطال\nكفاتك ودخول الكاف منقصة … كالشمس قلت وما للشمس أمثال\nالقاتل السيف في جسم القتيل به … وللسيوف كما للناس آجال\nله من الوحش ما اختارت أسنته … عير وهيق وخنساء وذيال\nلا يعرف الرزء في مال ولا ولد … إلا إذا حفز الضيفان ترحال\nتقري صوارمه الساعات عبط دم … كأنما الساع نزال وقفال\nلا يحرم البعد أهل البعد نائله … وغير عاجزة عنه الأطيفال\nوقد يلقبه المجنون حاسده … إذا اختلطن وبعض العقل عقال\nأنا له الشرف الأعلى تقدمه … فما الذي بتوقي ما أتى نالوا\nأبو شجاع أبو الشجعان قاطبة … هول نمته من الهيجاء أهوال\nتملك الحمد حتى ما لمفتخر … في الحمد حاء ولا ميم ولا دال\nلطفت رأيك في بري وتكرمتي … إن الكريم على العلياء يحتال\nحتى غدوت وللأخبار تجوال … وللكواكب في كفيك آمال\nوقد أطال ثنائي طول لابسه … إن الثناء على التنبال تنبال\nوإنما يبلغ الإنسان طاقته … ما كل ماشية بالرحل شملال"},{"id":"diwan-mutanabbi:91","bookId":"diwan-mutanabbi","type":"poem","seq":91,"chapter":"البحر: متقارب تام","title":"فديت بماذا يسر الرسول","page":"","text":"فديت بماذا يسر الرسول … وأنت الصحيح بذا لا العليل\nعواقب هذا تسوء العدو … وتثبت فيهم وهذا يزول"},{"id":"diwan-mutanabbi:92","bookId":"diwan-mutanabbi","type":"poem","seq":92,"chapter":"البحر: كامل تام","title":"لك يا منازل في القلوب منازل","page":"","text":"لك يا منازل في القلوب منازل … أقفرت أنت وهن منك أواهل\nيعلمن ذاك وما علمت وإنما … أولا كما يبكي عليه العاقل\nوأنا الذي اجتلب المنية طرفه … فمن المطالب والقتيل القاتل\nكم وقفة سجرتك شوقا بعدما … غري الرقيب بنا ولج العاذل\nإنعم ولذ فللأمور أواخر … أبدا إذا كانت لهن أوائل\nللهو آونة تمر كأنها … قبل يزودها حبيب راحل\nجمح الزمان فما لذيذ خالص … مما يشوب ولا سرور كامل\nحتى أبو الفضل ابن عبدالله رؤ … يته المنى وهي المقام الهائل\nمحجوبة بسرادق من هيبة … تثني الأزمة والمطي ذوامل\nللشمس فيه وللسحاب وللبحا … ر وللأسود وللرياح شمائل\nولديه ملعقيان والأدب المفا … د وملحياة وملممات مناهل\nيدري بما بك قبل تظهره له … من ذهنه ويجيب قبل تسائل\nكلماته قضب وهن فواصل … كل الضرائب تحتهن مفاصل\nهزمت مكارمه المكارم كلها … حتى كأن المكرمات قنابل\nلو طاب مولد كل حي مثله … ولد النساء وما لهن قوابل\nليزد بنو الحسن الشراف تواضعا … هيهات تكتم في الظلام مشاعل\nجفخت وهم لا يجفخون بها بهم … شيم على الحسب الأغر دلائل\nيا فخر فإن الناس فيك ثلاثة … مستعظم أو حاسد أو جاهل\nولقد علوت فما تبالي بعدما … عرفوا أيحمد أم يذم القائل\nأثني عليك ولو تشاء لقلت لي … قصرت فالإمساك عني نائل\nلا تجسر الفصحاء تنشد ههنا … بيتا ولكني الهزبر الباسل\nما نال أهل الجاهلية كلهم … شعري ولا سمعت بسحري بابل\nوإذا أتتك مذمتي من ناقص … من جوده في كل فج وابل\nمن لي بفهم أهيل عصر يدعي … أن يحسب الهندي فيهم باقل"},{"id":"diwan-mutanabbi:93","bookId":"diwan-mutanabbi","type":"poem","seq":93,"chapter":"البحر: كامل تام","title":"أمعفر الليث الهزبر بسوطه","page":"","text":"أمعفر الليث الهزبر بسوطه … لمن ادخرت الصارم المصقولا\nوقعت على الأردن منه بلية … نضدت بها هام الرفاق تلولا\nورد إذا ورد البحيرة شاربا … ورد الفرات زئيره والنيلا\nمتخضب بدم الفوارس لابس … في غيله من لبدتيه غيلا\nما قوبلت عيناه إلا ظنتا … تحت الدجى نار الفريق حلولا\nفي وحدة الرهبان إلا أنه … لا يعرف لاتحريم والتحليلا\nيطأ الثرى مترفقا من تيهه … فكأنه آس يجس عليلا\nألقى فريسته وبربر دونها … وقربت قربا خاله تطفيلا\nفتشابه الخلقان في إقدامه … وتخالفا في بذلك المأكولا"},{"id":"diwan-mutanabbi:94","bookId":"diwan-mutanabbi","type":"poem","seq":94,"chapter":"البحر: بسيط تام","title":"أحيا وأيسر ما قاسيت ما قتلا","page":"","text":"أحيا وأيسر ما قاسيت ما قتلا … والبين جار على ضعفي وما عدلا\nوالوجد يقوى كما تقوى النوى أبدا … والصبر ينحل في جسمي كما نحلا\nلولا مفارقة الأحباب ما وجدت … لها المنايا إلى أرواحنا سبلا\nبما بجفنيك من سحر صلي دنفا … يهوى الحياة وأما إن صددت فلا\nإلا يشب فلقد شابت له كبد … شيبا إذا خضبته سلوة نصلا\nيحن شوقا فلولا أن رائحة … تزوره من رياح الشرق ما عقلا\nها فانظري أو فظني بي تري حرقا … من لم يذق طرفا منها فقده وألا\nعل الأمير يرى ذلي فيشفع لي … إلى التي تركتني في الهوى مثلا"},{"id":"diwan-mutanabbi:95","bookId":"diwan-mutanabbi","type":"poem","seq":95,"chapter":"البحر: طويل","title":"إذا ما شربت الخمر صرفا مهنأ","page":"","text":"إذا ما شربت الخمر صرفا مهنأ … شربنا الذي من مثله شرب الكرم\nألا حبذا قوم نداما هم القنا … يسقونها ريا وساقيهم العزم"},{"id":"diwan-mutanabbi:96","bookId":"diwan-mutanabbi","type":"poem","seq":96,"chapter":"البحر: بسيط تام","title":"واحر قلباه ممن قلبه شبم","page":"","text":"واحر قلباه ممن قلبه شبم … ومن بجسمي وحالي عنده سقم\nمالي أكتم حبا قد برى جسدي … وتدعي حب سيف الدولة الأمم\nإن كان يجمعنا حب لغرته … فليت أنا بقدر الحب نقتسم\nقد زرته وسيوف الهند مغمدة … وقد نظرت إليه والسيوف دم\nفكان أحسن خلق الله كلهم … وكان أحسن ما في الأحسن الشيم\nأكلما رمت جيشا فانثنى هربا … تصرفت بك في آثاره الهمم\n … لعلمي أنه بعض الأنام\nيا أعدل الناس إلا في معاملتي … فيك الخصام وأنت الخصم والحكم\nأعيذها نظرات منك صادقة … أن تحسب الشحم فيمن شحمه ورم\nوما انتفاع أخي الدنيا بناظره … إذا استوت عنده الأنوار والظلم\nسيعلم الجمع ممن ضم مجلسنا … بأنني خير من تسقى به قدم\n … كنقص القادرين على التمام\nأنا الذي نظر الأعمى إلى أدبي … وأسمعت كلماتي من به صمم\nأنام ملء جفوني عن شواردها … ويسهر الخلق جراها ويختصم\nوجاهل مده في جهله ضحكي … حتى أتته يد فراسة وفم\nإذا رأيت نيوب الليث بارزة … فلا تظنن أن الليث يبتسم\nالخيل والليل والبيداء تعرفني … والسيف والرمح والقرطاس والقلم\nيا من يعز علينا أن نفارقهم … وجداننا كل شيء بعدكم عدم\nما كان أخلقنا منكم بتكرمة … لو أن أمركم من أمرنا أمم\nإن كان سركم ما قال حاسدنا … فما لجرح إذا أرضاكم ألم\nكم تطلبون لنا عيبا فيعجزكم … ويكره الله ما تأتون والكرم\nأبعد العيب والنقصان من شرفي … أنا الثريا وذان الشيب والهرم\nشر البلاد مكان لا صديق به … وشر ما يكسب الإنسان ما يصم\nهذا عتابك إلا أنه مقة … قد ضمن الدر إلا أنه كلم"},{"id":"diwan-mutanabbi:97","bookId":"diwan-mutanabbi","type":"poem","seq":97,"chapter":"البحر: وافر تام","title":"أما في هذه الدنيا كريم","page":"","text":"أما في هذه الدنيا كريم … تزول به عن القلب الهموم\nأما في هذه الدنيا مكان … يسر بأهله الجار المقيم\nحصلت بأرض مصر على عبيد … كأن الحر بينهم يتيم\nكأن الأسود اللابي فيهم … غراب حوله رخم وبوم\nأخذت بمدحه فرأيت لهوا … مقالي للأحيمق يا حليم\nولما أن هجوت رأيت عيا … مقالي لابن آوى يا لئيم\nفهل من عاذر في ذا وفي ذا … فمدفوع إلى السقم السقيم\nإذا أتت الإساءة من وضيع … ولم ألم المسي فمن ألوم"},{"id":"diwan-mutanabbi:98","bookId":"diwan-mutanabbi","type":"poem","seq":98,"chapter":"البحر: وافر تام","title":"أعن إذني تمر الريح رهوا","page":"","text":"أعن إذني تمر الريح رهوا … ويسري كلما شئت الغمام\nولكن الغمام له طباع … تبجسه بها وكذا الكرام\nعلى قدر أهل العزم تأتي العزائم … وتأتي على قدر الكرام المكارم\nوتعظم في عين الصغير صغارها … وتصغر في عين العظيم العظائم\nيكلف سيف الدولة الجيش همه … وقد عجزت عنه الجيوش الخضارم\nويطلب عند الناس ما عند نفسه … وذلك مالا تدعيه الضراغم\nيفدي أتم الطير عمرا سلاحه … نسور افلا أحداثها والقشاعم\nفلم يبق إلا صارم أو ضبارم … وقد خلقت أسيافه والقوائم\nهل الحدث الحمراء تعرف كونها … وتعلم أي الساقين الغمائم\nسقتها الغمام الغر قبل نزوله … فلما دنا منها سقتها الجماجم\nبناها فأعلى والقنا يقرع القنا … وموج المنايا حولها متلاطم\nوكان بها مثل الجنون فأصبحت … ومن جثث القتلى عليها تمائم\nأتوك يجرون الحديد كأنهم … سروا بجياد مالهن قوائم\nإذا برقوا لم تعرف البيض منهم … ثيابهم من مثلها والعمائم\nخميس بشرق الأرض والغرب زحفه … وفي أذن الجوزاء منه زمازم\nتجمع فيه كل لسن وأمة … فما يفهم الحداث إلا التراجم\nتقطع ما لا يقطع الدرع والقنا … وفر من الفرسان من لا يصادم\nوقفت وما في الموت شك لواقف … كأنك في جفن الردى وهو نائم\nتمر بك الأبطال كلمى هزيمة … ووجهك وضاح وثغرك باسم\nأينكر ريح الليث حتى يذوقه … إلى قول قوم أنت بالغيب عالم\nنثرتهم فوق الأحيدب كله … كما نثرت فوق العروس الدراهم\nألا أيها السيف الذي ليس مغمدا … ولا فيه مرتاب ولا منه عاصم\nهنيئا لضرب الهام والمجد والعلى … وراجيك والإسلام أنك سالم\nوقد حاكموها والمنايا حواكم … وتفليقه هام العدى بك دائم"},{"id":"diwan-mutanabbi:99","bookId":"diwan-mutanabbi","type":"poem","seq":99,"chapter":"البحر: بسيط تام","title":"بم التعلل لا أهل ولا وطن","page":"","text":"بم التعلل لا أهل ولا وطن … ولا نديم ولا كأس ولا سكن\nأريد من زمني ذا أن يبلغني … ما ليس يبلغه من نفسه الزمن\nلا تلق دهرك إلا غير مكترث … مادام يصحب فيه روحك البدن\nفما يديم سرور ما سررت به … ولا يرد عليك الفائت الحزن\nمما أضر بأهل العشق أنهم … هووا وما عرفوا الدنيا وما فطنوا\nتفني عيونهم دمعا وأنفسهم … في إثر كل قبيح وجهه حسن\nيا من نعيت على بعد بمجلسه … كل بما زعم الناعون مرتهن\nكم قد قتلت وكم قد مت عندكم … ثم انتفضت فزال القبر والكفن\nقد كان شاهد دفني قبل قولهم … جماعة ثم ماتوا قبل من دفنوا\nما كل ما يتمنى المرء يدركه … تجري الرياح بما لا تشتهي السفن\nجزاء كل قريب منكم ملل … وحظ كل محب منكم ضغن\nإني أصاحب حلمي وهو بي كرم … ولا أصاحب حلمي وهو بي جبن\nسهرت بعد رحيلي وحشة لكم … ثم استمر مريري وارعوى الوسن\nوإن بليت بود مثل ودكم … فإنني بفراق مثله قمن"},{"id":"diwan-mutanabbi:100","bookId":"diwan-mutanabbi","type":"poem","seq":100,"chapter":"البحر: خفيف تام","title":"صحب الناس قبلنا ذا الزمانا","page":"","text":"صحب الناس قبلنا ذا الزمانا … وعناهم من شأنه ما عنانا\nوتولوا بغصة كلهم من … ه وإن سر بعضهم أحيانا\nكلما أنبت الزمان قناة … ركب المرء في القناة سنانا\nومراد النفوس أصغر من أن … تتعادى فيه وأن تتفانى\nغير أن الفتى يلاقي المنايا … كالحات ولا يلاقي الهوانا\nولو أن الحياة تبقى لحي … لعددنا أضلنا الشجعانا\nوإذا لم يكن من الموت بد … فمن العجز أن تكون جبانا"},{"id":"diwan-mutanabbi:101","bookId":"diwan-mutanabbi","type":"poem","seq":101,"chapter":"البحر: بسيط تام","title":"أبلى الهوى أسفا يوم النوى بدني","page":"","text":"أبلى الهوى أسفا يوم النوى بدني … وفرق الهجر بين الجفن والوسن\nروح تردد في مثل الخلال إذا … أطارت الريح عنه الثوب لم يبن\nكفى بجسمي نحولا أنني رجل … لولا مخاطبتي إياك لم ترني"},{"id":"diwan-mutanabbi:102","bookId":"diwan-mutanabbi","type":"poem","seq":102,"chapter":"البحر: بسيط تام","title":"كتمت حبك حتى منك تكرمة","page":"","text":"كتمت حبك حتى منك تكرمة … ثم استوى فيه اسراري وإعلاني\nكأنه زاد حتى فاض عن جسدي … فصار سقمي به في جسم كتماني"},{"id":"diwan-mutanabbi:103","bookId":"diwan-mutanabbi","type":"poem","seq":103,"chapter":"البحر: كامل تام","title":"الرأي قبل شجاعة الشجعان","page":"","text":"الرأي قبل شجاعة الشجعان … هو أول وهي المحل الثاني\nفإذا هما اجتمعا لنفس حرة … بلغت من العلياء كل مكان\nولربما طعن الفتى أقرانه … بالرأي قبل تطاعن الأقران\nلولا العقول لكان أدنى ضيغم … أدنى إلى شرف من الإنسان"},{"id":"diwan-mutanabbi:104","bookId":"diwan-mutanabbi","type":"poem","seq":104,"chapter":"البحر: منسرح","title":"ألناس ما لم يروك أشباه","page":"","text":"ألناس ما لم يروك أشباه … والدهر لفظ وأنت معناه\nوالجود عين وأنت ناظرها … والبأس باع وأنت يمناه\nيا راحلا كل من يودعه … مودع دينه ودنياه\nإن كان فيما نراه من كرم … فيك مزيد فزادك الله"},{"id":"diwan-mutanabbi:105","bookId":"diwan-mutanabbi","type":"poem","seq":105,"chapter":"البحر: وافر تام","title":"لئن تك طيء كانت لئاما","page":"","text":"لئن تك طيء كانت لئاما … فألأمها ربيعة أو بنوه\nوإن تك طيء كانت كراما … فوردان لغيرهم أبوه\nمررنا منه في حسمى بعبد … يمج اللؤم منخره وفوه\nأشذ بعرسه عني عبيدي … فأتلفهم ومالي أتلفوه\nفإن شقيت بأيديهم جيادي … لقد شقيت بمنصلي الوجوه"},{"id":"diwan-mutanabbi:106","bookId":"diwan-mutanabbi","type":"poem","seq":106,"chapter":"البحر: منسرح","title":"أوه بديل من قولتي واها","page":"","text":"أوه بديل من قولتي واها … لمن نأت والبديل ذكراها\nأو لمن لا أرى محاسنها … وأصل واها وأوه مرآها\nشامية طالما خلوت بها … تبصر في ناظري محياها\nفقبلت ناظري تغالطني … وإنما قبلت به فاها\nكل جريح ترجى سلامته … وليته لا يزال مأواها\nتبل خدي كلما ابتسمت … من مطر برقه ثناياها\nلقيننا والحمول سائرة … وإنما لذة ذكرناها\nأحب حمصا إلى خناصرة … وكل نفس تحب محياها\nحيث التقى خدها وتفاح لب … نان وثغري على حمياها\nجعلته في المدام أفواها … دان له شرقها ومغربها\nوقد رأيت الملوك قاطبة … وكيف تخفى التي زيادتها\nأبا شجاع بفارس عضد الدو … لة فنا خسرو شهنشاها\nدنيا وأبنائها وما تاها … أنفس أمواله وأسناها\nلا تجد الخمر في مكارمه … إذا انتشى خلة تلافاها\nتصاحب الراح أريحيته … فتسقط الراح دون أدناها\nتشرق تيجانه بغرته … إشراق الفاظه بمعناها\nتجمعت في فؤاده همم … ملء فؤاد الزمان إحداها\nألفارس المتقى السلاح به ال … مثنى عليه الوغى وخيلاها\nأو ذكرت حلة غزوناها … غير أمير وإن بها باهى\nلو كفر العالمون نعمته … لما عدت نفسه سجاياها\nكالشمس لا تبتغي بما صنعت … معرفة عندهم ولا جاها\nألناس كالعابدين آلهة … وعبده كالموحد الله"},{"id":"diwan-mutanabbi:107","bookId":"diwan-mutanabbi","type":"poem","seq":107,"chapter":"البحر: طويل","title":"كفى بك داء أن ترى الموت شافيا","page":"","text":"كفى بك داء أن ترى الموت شافيا … وحسب المنايا أن يكن أمانيا\nتمنيتها لما تمنيت أن ترى … صديقا فأعيا أو عدوا مداجيا\nإذا كنت ترضى أن تعيش بذلة … فلا تستعدن الحسام اليمانيا\nحببتك قلبي قبل حبك من نأى … وقد كان غدارا فكن أنت وافيا\nأقل اشتياقا أيها القلب ربما … رأيتك تصفي الود من ليس صافيا\nقواصد كافور توارك غيره … ومن قصد\nيبيد عداوات البغاة بلطفه … فإن لم تبد منهم أباد الأعاديا\nأبا المسك ذا الوجه الذي كنت تائقا … إليه وذا اليوم الذي كنت راجيا"},{"id":"diwan-mutanabbi:108","bookId":"diwan-mutanabbi","type":"poem","seq":108,"chapter":"البحر: طويل","title":"أريك الرضى لو أخفت النفس خافيا","page":"","text":"أريك الرضى لو أخفت النفس خافيا … وما أنا عن نفسي ولا عنك راضيا\nأمينا وإخلافا وغدرا وخسة … وجبنا ، أشخصا لحت لي أم مخازيا\nتظن ابتساماتي رجاء وغبطة … وما أنا إلا ضاحك من رجائيا\nوتعجبني رجلاك في النعل إنني … رأيتك ذا نعل إذا كنت حافيا\nوإنك لا تدري ألونك أسود … من الجهل أم قد صار أبيض صافيا\nولولا فضول الناس جئتك مادحا … بما كنت في سري به لك هاجيا\nفأصبحت مسرورا بما أنا منشد … وإن كان بالإنشاد هجوك غاليا\nومثلك يؤتى من بلاد بعيدة … ليضحك ربات الحداد البواكيا"}]};